{
    var tcs = new TaskCompletionSource<Location>(
        TaskCreationOptions.RunContinuationsAsynchronously);   // why — in a card below
    void OnFix(Location l)    => tcs.TrySetResult(l);
    void OnError(Exception e) => tcs.TrySetException(e);

    gps.OnFix += OnFix; gps.OnError += OnError;
    using var reg = ct.Register(() => tcs.TrySetCanceled(ct));
    try
    {
        gps.Start();
        return await tcs.Task;
    }
    finally { gps.OnFix -= OnFix; gps.OnError -= OnError; }
