class SimpleQueue<T>
{
    private readonly Queue<T> _items = new();
    private readonly object _gate = new();

    public void Put(T item)
    {
        lock (_gate)
        {
            _items.Enqueue(item);
            Monitor.Pulse(_gate);        // wake one waiter
        }
    }

    public T Take()
    {
        lock (_gate)
        {
            while (_items.Count == 0)
                Monitor.Wait(_gate);     // release the lock and sleep
            return _items.Dequeue();
        }
    }
}

public T Take()
{
    lock (_gate)
    {
        if (_items.Count == 0)
            Monitor.Wait(_gate);
        return _items.Dequeue();
    }
}

