        cache.TryRemove(KeyValuePair.Create(key, lazy));
        throw;
    }
}

static void Add(int amount)
{
    int current = Volatile.Read(ref _total);
    while (true)
    {
        int seen = Interlocked.CompareExchange(ref _total, current, current + amount);
        if (seen == current) return;
        current = seen;
    }
}

private readonly Lock _gate = new();

public async Task SaveAsync(Data d)
{
    lock (_gate)
    {
        await File.WriteAllTextAsync(PathToFile, d.ToJson());
    }
}
